import type { Register } from 'claude-code'

import { KnownSecrets, MASK, extract, redact, summary } from './redact'

/**
 * secret-redact — masque les secrets dans les sorties d'outils avant que
 * Claude ne les lise.
 *
 * Trois couches :
 *  0. `session.start` : apprend les VALEURS des secrets du projet (wp-config,
 *     .env, …) et des listes utilisateur, pour les masquer partout ensuite,
 *     quel que soit le contexte (dump SQL, log, HTML, JSON…).
 *  1. `tool.call` sur Read et Bash : réécrit l'enregistrement typé du résultat
 *     (file.content / stdout / stderr). Les valeurs reconnues sont apprises.
 *  2. `session.append` sur la porte `tool-result` : filet générique pour tous
 *     les autres outils (Grep, Edit, MCP, …).
 *
 * `/secret-redact` affiche l'état : valeurs apprises, sources, total masqué.
 */

/** Listes utilisateur : une valeur par ligne, ou LABEL=valeur. */
const LIST_GLOBAL = '.claude/secret-redact.txt' // sous $HOME
const LIST_PROJECT = '.secret-redact' // sous le cwd

/** Fichiers porteurs de secrets lus au démarrage, relatifs au cwd. */
const SECRET_FILES = [
  'wp-config.php',
  'auth.json',
  '.npmrc',
  'config/database.php',
  'config/parameters.yml',
  'docker-compose.yml',
  'docker-compose.override.yml',
]
/** Sous-dossiers où chercher aussi `wp-config.php` et `.env*`. */
const SUBDIRS = ['', 'public', 'public_html', 'web', 'www', 'htdocs', 'wordpress', 'wp', 'app', 'site']

const known = new KnownSecrets()
let total = 0
const sources: string[] = []
/** Diagnostic pour /secret-redact : cwd et chemins de listes examinés. */
let diagCwd = ''
const diagLists: string[] = []

/** Dossiers de cwd vers la racine, cwd d'abord (8 niveaux au plus). */
function parents(cwd: string): string[] {
  const out: string[] = []
  let dir = cwd.replace(/\/+$/, '')
  for (let i = 0; i < 8 && dir; i++) {
    out.push(dir)
    const cut = dir.lastIndexOf('/')
    if (cut <= 0) break
    dir = dir.slice(0, cut)
  }
  return out
}

const status = ($: { ui: { status: (t?: string) => unknown } }) =>
  $.ui.status(`🔒 ${total} masqué${total > 1 ? 's' : ''} · ${known.size} valeur${known.size > 1 ? 's' : ''} · ${known.keyCount} clé${known.keyCount > 1 ? 's' : ''}`)

const FAILED = (tool: string) =>
  `secret-redact : le masquage a échoué, la sortie de ${tool} est retenue par précaution.` +
  (tool === 'Bash' ? ' La commande a bien été exécutée ; ne la relance pas si elle a des effets de bord.' : '')

const NOTE = (line: string) =>
  `${line}. Les valeurs existent mais te sont cachées ; ne cherche pas à les obtenir par un autre outil ni à les reconstituer.`

const isListFile = (path: string) => path.endsWith('/' + LIST_PROJECT) || path.endsWith('/' + LIST_GLOBAL) || path === LIST_PROJECT
/** Mention d'une liste dans une commande shell. */
const LIST_RE = /(?:^|[\s/'"=])(?:\.secret-redact|secret-redact\.txt)(?=$|[\s'"|;&>)])/

export const register: Register = (on) => {
  // Couche 0 — apprentissage des valeurs au démarrage.
  on('session.start', async ($, e, next) => {
    const cwd = await $.session.cwd()
    const home = await $.env.get('HOME')
    sources.length = 0
    diagLists.length = 0
    diagCwd = cwd

    const tryList = async (path: string): Promise<boolean> => {
      if (!(await $.fs.exists(path).catch(() => false))) {
        diagLists.push(`${path} : absente`)
        return false
      }
      const text = await $.fs.read(path).catch(() => '')
      const n = known.learnList(text)
      diagLists.push(`${path} : ${n} entrée${n > 1 ? 's' : ''}`)
      if (n > 0) sources.push(`${path} (liste, ${n})`)
      return true
    }
    const tryFile = async (path: string) => {
      if (!(await $.fs.exists(path).catch(() => false))) return
      const text = await $.fs.read(path).catch(() => '')
      const n = known.learnAll(extract(text))
      if (n > 0) sources.push(`${path.replace(cwd + '/', '')} (${n})`)
    }

    if (home) await tryList(`${home}/${LIST_GLOBAL}`)
    // Liste projet : dans le cwd, sinon dans un dossier parent (racine du projet).
    for (const dir of parents(cwd)) {
      if (await tryList(`${dir}/${LIST_PROJECT}`)) break
    }

    for (const sub of SUBDIRS) {
      const dir = sub ? `${cwd}/${sub}` : cwd
      if (sub && !(await $.fs.exists(dir).catch(() => false))) continue
      await tryFile(`${dir}/wp-config.php`)
      const entries = await $.fs.list(dir).catch(() => [])
      for (const entry of entries) {
        if (entry.kind === 'file' && /^\.env(\..+)?$/.test(entry.name) && entry.name !== '.env.example') {
          await tryFile(`${dir}/${entry.name}`)
        }
      }
    }
    for (const f of SECRET_FILES) await tryFile(`${cwd}/${f}`)

    await $.command.register({ name: 'secret-redact', description: 'État du masquage : valeurs connues, sources, total masqué.' })
    if (known.size > 0 || known.keyCount > 0) {
      $.ui.log(`secret-redact : ${known.size} valeur${known.size > 1 ? 's' : ''} et ${known.keyCount} clé${known.keyCount > 1 ? 's' : ''} apprises depuis ${sources.join(', ')}`)
      status($)
    }
    return next(e)
  })

  on('command.run', { command: 'secret-redact' }, async () => ({
    text:
      `secret-redact\n` +
      `  valeurs connues : ${known.size}\n` +
      `  clés déclarées  : ${known.keyCount}` +
      (known.coveredKeys.length ? ` (+${known.coveredKeys.length} déjà couverte${known.coveredKeys.length > 1 ? 's' : ''} par défaut : ${known.coveredKeys.join(', ')})` : '') +
      `\n` +
      `  sources         : ${sources.length ? sources.join(', ') : 'aucune'}\n` +
      `  masquées        : ${total} (session)\n` +
      `  cwd             : ${diagCwd}\n` +
      `  listes          :\n` +
      diagLists.map((l) => `    ${l}`).join('\n') +
      `\n  (une liste modifiée est relue au prochain démarrage de Claude Code)`,
  }))

  // Couche 1a — Read : le contenu du fichier lu.
  on('tool.call', { tool: 'Read' }, async ($, e, next) => {
    const got = await next(e)
    if (got.deny !== undefined || got.isError === true) return got
    const rec = got.result
    if (rec.type !== 'text' || typeof rec.file?.content !== 'string') return got
    const where = e.file_path.split('/').pop() ?? e.file_path

    // Une liste de secrets ne se lit pas, même masquée ligne à ligne.
    if (isListFile(e.file_path)) {
      const lines = rec.file.content.split('\n').filter((l) => l.trim() && !l.trim().startsWith('#')).length
      known.learnList(rec.file.content)
      $.ui.log(`secret-redact : ${where} retenu en entier (${lines} entrées)`)
      return {
        result: { ...rec, file: { ...rec.file, content: `${MASK('SECRET_LIST')} — ${lines} entrée${lines > 1 ? 's' : ''}, fichier réservé au mod secret-redact.` } },
        context: [...(got.context ?? []), NOTE(`secret-redact : ${where} est une liste de secrets, son contenu t'est caché`)],
      }
    }

    const r = redact(rec.file.content, known)
    known.learnAll(r.found)
    if (r.count === 0) return got
    total += r.count
    $.ui.log(summary(r, where))
    status($)
    return {
      result: { ...rec, file: { ...rec.file, content: r.text } },
      context: [...(got.context ?? []), NOTE(summary(r, where))],
    }
  }).catch(($, e) => ({ deny: FAILED(e.tool) }))

  // Couche 1b — Bash : stdout et stderr.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    // Une commande qui vise une liste de secrets ne s'exécute pas (cat, grep, sed, …).
    if (LIST_RE.test(e.command)) {
      return { deny: 'secret-redact : cette commande lit une liste de secrets réservée au mod. Son contenu ne t\'est pas accessible ; continue sans.' }
    }
    const got = await next(e)
    if (got.deny !== undefined || got.isError === true) return got
    const rec = got.result
    // Commande passée en arrière-plan ou sortie persistée : rien à masquer ici.
    if (typeof rec.stdout !== 'string' && typeof rec.stderr !== 'string') return got
    const out = redact(typeof rec.stdout === 'string' ? rec.stdout : '', known)
    const err = redact(typeof rec.stderr === 'string' ? rec.stderr : '', known)
    known.learnAll([...out.found, ...err.found])
    const count = out.count + err.count
    if (count === 0) return got
    total += count
    const merged = { count, labels: [...new Set([...out.labels, ...err.labels])] }
    const where = `la sortie de \`${e.command.slice(0, 40)}${e.command.length > 40 ? '…' : ''}\``
    $.ui.log(summary(merged, where))
    status($)
    return {
      result: { ...rec, stdout: out.text, stderr: err.text },
      context: [...(got.context ?? []), NOTE(summary(merged, where))],
    }
  }).catch(($, e) => ({ deny: FAILED(e.tool) }))

  // Couche 2 — toute ligne stockée dans la conversation hors prompt et réponse :
  // résultats d'outils (Grep, Edit, MCP, …), sortie d'une commande `!` (qui ne
  // passe pas par l'outil Bash), notices, pièces jointes du moteur, contexte des
  // hooks de settings, livraisons entre sessions, résumés de compaction.
  on('session.append', { door: ['tool-result', 'tool-message', 'command', 'notice', 'attachment', 'hook-context', 'delivery', 'compaction'] }, async ($, e, next) => {
    let count = 0
    const labels = new Set<string>()
    const scrub = (text: string) => {
      const r = redact(text, known)
      known.learnAll(r.found)
      if (r.count === 0) return null
      count += r.count
      r.labels.forEach((l) => labels.add(l))
      return r.text
    }
    const scrubParts = (c: unknown): unknown => {
      if (typeof c === 'string') return scrub(c) ?? c
      if (!Array.isArray(c)) return c
      let changed = false
      const parts = c.map((p: unknown) => {
        const part = p as { type?: string; text?: unknown }
        if (part.type !== 'text' || typeof part.text !== 'string') return p
        const t = scrub(part.text)
        if (t === null) return p
        changed = true
        return { ...part, text: t }
      })
      return changed ? parts : c
    }
    const content = e.message.content.map((block) => {
      if (block.type === 'text' && typeof block.text === 'string') {
        const t = scrub(block.text)
        return t === null ? block : { ...block, text: t }
      }
      if (block.type === 'tool_result') {
        const c = scrubParts(block.content)
        return c === block.content ? block : { ...block, content: c }
      }
      return block
    })
    if (count === 0) return next(e)
    total += count
    const where =
      e.origin.kind === 'tool' ? `la sortie de ${e.origin.tool}` :
      e.door === 'command' || e.message.name === 'local_command' ? "la sortie d'une commande !" :
      `une ligne ${e.door}`
    $.ui.log(summary({ count, labels: [...labels] }, where))
    status($)
    return next({ ...e, message: { ...e.message, content } })
  })
}

