/**
 * Moteur de masquage : pur, sans dépendance, testable.
 *
 * Deux mécanismes complémentaires :
 *  - des RÈGLES (regex) qui reconnaissent un secret à sa forme : clé nommée
 *    (DB_PASSWORD=…), format connu (AKIA…, ghp_…), bloc PEM, URL avec
 *    identifiants ;
 *  - des VALEURS CONNUES (`KnownSecrets`) : des chaînes littérales apprises
 *    (fichiers du projet, liste de l'utilisateur, matches précédents) masquées
 *    partout où elles apparaissent, quel que soit le contexte.
 *
 * Chaque masquage remplace la VALEUR par `[REDACTED:<label>]` en conservant
 * le nom de la clé, pour que Claude sache qu'une valeur existe sans la lire.
 */

export type Found = { label: string; value: string }

export type Redaction = {
  /** Texte après masquage. */
  text: string
  /** Nombre de valeurs masquées. */
  count: number
  /** Labels distincts rencontrés (DB_PASSWORD, AWS_ACCESS_KEY, …). */
  labels: string[]
  /** Valeurs reconnues par les règles, à apprendre pour les masquer ailleurs. */
  found: Found[]
}

type Rule = {
  /** Nom de la règle, label par défaut. */
  name: string
  pattern: RegExp
  /** Construit le remplacement ; `null` = ne pas masquer (placeholder). */
  replace: (m: string, ...g: string[]) => string | null
  /** Label rapporté ; par défaut `name`. */
  label?: (m: string, ...g: string[]) => string
  /** La valeur brute du secret dans le match ; par défaut le match entier. */
  value?: (m: string, ...g: string[]) => string
}

export const MASK = (label: string) => `[REDACTED:${label}]`
const MASK_RE = /\[REDACTED:[^\]]*\]/g

/** Clés dont la valeur est un secret, quel que soit le format (env, ini, yaml, json, php). */
const SECRET_KEY =
  '(?:[A-Za-z0-9_]*_)?(?:PASSWORD|PASSWD|PASSPHRASE|PASS|SECRET|SECRET_KEY|TOKEN|API_?KEY|PRIVATE_KEY|ACCESS_KEY|ACCESS_KEY_ID|AUTH_KEY|NONCE_KEY|LOGGED_IN_KEY|APP_KEY|ENCRYPTION_KEY|SIGNING_KEY|AUTH_SALT|SALT|CLIENT_SECRET|DSN|CREDENTIALS?)(?:_[A-Za-z0-9_]*)?'

/** Valeurs à ne pas masquer : vides, placeholders, variables, chemins. */
const PLACEHOLDER =
  /^(?:|\s*|\$\{?[A-Za-z_][A-Za-z0-9_]*\}?|<[^>]*>|x{3,}|\*{3,}|\.{3,}|changeme|change_me|your[-_ ]?[a-z_]*|put .*here|null|none|false|true|0|\/[^\s]*|\.{1,2}\/[^\s]*|~\/[^\s]*)$/i

const unquote = (v: string) => v.trim().replace(/^(['"])(.*)\1$/, '$2')
export const isPlaceholder = (v: string) => PLACEHOLDER.test(unquote(v))

/**
 * Suffixes qui font d'une clé « secrète » un paramètre et non un secret :
 * TOKEN_TTL, API_KEY_HEADER, PASSWORD_RESET_URL, SECRET_KEY_LENGTH, SALT_ROUNDS…
 * Appliqué aux règles par défaut seulement, jamais aux clés déclarées par
 * l'utilisateur.
 */
const NON_SECRET_SUFFIX =
  /_(?:URL|URI|PATH|FILE|DIR|HOST|PORT|TTL|EXPIRY|EXPIRES|EXPIRATION|LIFETIME|TIMEOUT|LENGTH|MIN|MAX|SIZE|ROUNDS|ENABLED|DISABLED|REQUIRED|TYPE|NAME|ID|ALGO|ALGORITHM|HEADER|PREFIX|SUFFIX|FORMAT|VERSION|MODE|METHOD|FIELD|COLUMN|LABEL|PLACEHOLDER)$/i
export const isParameterKey = (key: string) => NON_SECRET_SUFFIX.test(key)

/**
 * Une valeur apprise n'est masquée PARTOUT que si elle ressemble à un
 * secret : au moins 8 caractères, deux classes de caractères (ou 16+), et
 * ni un hôte, ni une IP, ni une URL, ni un e-mail, ni un chemin. Sinon
 * `localhost` ou `wordpress` disparaîtraient de toutes les sorties.
 * Elle reste masquée à côté de son nom par les règles.
 */
export function looksSecret(value: string): boolean {
  const v = unquote(value)
  if (v.length < 8 || isPlaceholder(v) || v.includes('[REDACTED:')) return false
  if (/^[\d.:]+$/.test(v)) return false // IP, port
  if (/^[a-z0-9-]+(?:\.[a-z0-9-]+)+(?::\d+)?$/i.test(v)) return false // nom d'hôte
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(v)) return false // URL (ses identifiants sont appris à part)
  if (/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(v)) return false // e-mail
  if (/^[\/~.]/.test(v)) return false // chemin
  const classes = [/[a-z]/, /[A-Z]/, /\d/, /[^A-Za-z0-9]/].filter((re) => re.test(v)).length
  return classes >= 2 || v.length >= 16
}

/** Règles « clé nommée » : construites pour une alternance de noms de clés donnée. */
function namedRules(keys: string, builtin: boolean): Rule[] {
  const skip = (key: string, value: string) => isPlaceholder(value) || (builtin && isParameterKey(key))
  return [
    // wp-config.php : define( 'DB_PASSWORD', 'xxx' ) et sels/clés d'authentification.
    {
      name: 'WP_DEFINE',
      pattern: new RegExp(`(define\\s*\\(\\s*(['"])(${keys})\\2\\s*,\\s*)(['"])((?:\\\\.|(?!\\4).)*)\\4`, 'gi'),
      replace: (_m, head, _q1, key, q2, value) => (skip(key, value) ? null : `${head}${q2}${MASK(key.toUpperCase())}${q2}`),
      label: (_m, _h, _q, key) => key.toUpperCase(),
      value: (_m, _h, _q, _k, _q2, value) => value,
    },
    // PHP : 'password' => 'xxx', "db_pass" => "xxx", $password = 'xxx'
    {
      name: 'PHP_ASSIGN',
      pattern: new RegExp(`((?:['"](${keys})['"]\\s*=>|\\$(${keys})\\s*=)\\s*)(['"])((?:\\\\.|(?!\\4).)*)\\4`, 'gi'),
      replace: (_m, head, k1, k2, q, value) => (skip(k1 ?? k2, value) ? null : `${head}${q}${MASK((k1 ?? k2).toUpperCase())}${q}`),
      label: (_m, _h, k1, k2) => (k1 ?? k2).toUpperCase(),
      value: (_m, _h, _k1, _k2, _q, value) => value,
    },
    // JSON / YAML à clé citée : "password": "xxx", 'api_key': 'xxx'
    {
      name: 'JSON_KEY',
      pattern: new RegExp(`((['"])(${keys})\\2\\s*:\\s*)(['"])((?:\\\\.|(?!\\4).)*)\\4`, 'gi'),
      replace: (_m, head, _q1, key, q2, value) => (skip(key, value) ? null : `${head}${q2}${MASK(key.toUpperCase())}${q2}`),
      label: (_m, _h, _q, key) => key.toUpperCase(),
      value: (_m, _h, _q, _k, _q2, value) => value,
    },
    // .env / ini / yaml / shell : DB_PASSWORD=xxx, api_key: xxx, export TOKEN="xxx"
    {
      name: 'ENV_ASSIGN',
      // Tolère une balise ouvrante/fermante sur la ligne (sortie d'une commande `!` : <local-command-stdout>…</local-command-stdout>).
      pattern: new RegExp(`(^[ \\t]*(?:<[a-z-]+>)?[ \\t]*(?:export[ \\t]+)?(${keys})[ \\t]*[=:][ \\t]*)(.+?)[ \\t]*(?:</[a-z-]+>)?$`, 'gim'),
      replace: (_m, head, key, value) => {
        if (skip(key, value)) return null
        const q = /^['"]/.test(value) ? value[0] : ''
        return `${head}${q}${MASK(key.toUpperCase())}${q}`
      },
      label: (_m, _h, key) => key.toUpperCase(),
      value: (_m, _h, _k, value) => unquote(value),
    },
  ]
}

const RULES: Rule[] = [
  // Bloc PEM (clé privée) : masqué en entier.
  {
    name: 'PRIVATE_KEY_PEM',
    pattern: /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g,
    replace: () => `REDACTED-PRIVATE-KEY-BY-SLOPSHOPPER`,
  },

  ...namedRules(SECRET_KEY, true),

  // URL avec identifiants : mysql://user:REDACTED@host, https://user:PASS@host
  {
    name: 'URL_CREDENTIALS',
    pattern: /([a-z][a-z0-9+.-]*:\/\/[^\s:/@"']+:)([^\s@/"']+)(@)/gi,
    replace: (_m, head, _pass, at) => `${head}${MASK('URL_PASSWORD')}${at}`,
    label: () => 'URL_PASSWORD',
    value: (_m, _h, pass) => pass,
  },

  // En-têtes HTTP : Authorization: Bearer xxx / Basic xxx / X-Api-Key: xxx
  {
    name: 'AUTHORIZATION_HEADER',
    pattern: /((?:authorization|x-api-key|x-auth-token)["']?\s*[:=]\s*["']?(?:(?:bearer|basic|token)\s+)?)([A-Za-z0-9._~+/=-]{8,})/gi,
    replace: (_m, head, tok) => (isPlaceholder(tok) ? null : `${head}${MASK('AUTHORIZATION')}`),
    label: () => 'AUTHORIZATION',
    value: (_m, _h, tok) => tok,
  },

  // Formats de tokens connus, où qu'ils apparaissent (valeur = match entier).
  { name: 'AWS_ACCESS_KEY', pattern: /\b(?:AKIA|ASIA)[0-9A-Z]{16}\b/g, replace: () => MASK('AWS_ACCESS_KEY') },
  { name: 'GITHUB_TOKEN', pattern: /\b(?:gh[pousr]_[A-Za-z0-9]{36,}|github_pat_[A-Za-z0-9_]{22,})\b/g, replace: () => MASK('GITHUB_TOKEN') },
  { name: 'SLACK_TOKEN', pattern: /\bxox[baprs]-[A-Za-z0-9-]{10,}\b/g, replace: () => MASK('SLACK_TOKEN') },
  { name: 'STRIPE_KEY', pattern: /\b[sr]k_(?:live|test)_[A-Za-z0-9]{16,}\b/g, replace: () => MASK('STRIPE_KEY') },
  { name: 'GOOGLE_API_KEY', pattern: /\bAIza[0-9A-Za-z_-]{35}\b/g, replace: () => MASK('GOOGLE_API_KEY') },
  { name: 'ANTHROPIC_KEY', pattern: /\bsk-ant-[A-Za-z0-9_-]{20,}\b/g, replace: () => MASK('ANTHROPIC_KEY') },
  { name: 'OPENAI_KEY', pattern: /\bsk-(?!ant-)[A-Za-z0-9_-]{20,}\b/g, replace: () => MASK('OPENAI_KEY') },
  { name: 'SENDGRID_KEY', pattern: /\bSG\.[A-Za-z0-9_-]{22}\.[A-Za-z0-9_-]{43}\b/g, replace: () => MASK('SENDGRID_KEY') },
  { name: 'JWT', pattern: /\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g, replace: () => MASK('JWT') },
]

/** Longueur minimale d'une valeur de liste : en dessous, trop de faux positifs. */
export const MIN_VALUE_LENGTH = 6

const BUILTIN_KEY = new RegExp(`^${SECRET_KEY}$`, 'i')

/**
 * Valeurs littérales à masquer partout. Apprises des fichiers du projet, de
 * la liste de l'utilisateur et des matches des règles.
 */
export class KnownSecrets {
  private readonly map = new Map<string, string>()
  private alternation: RegExp | null = null
  private readonly keys = new Set<string>()
  private readonly covered = new Set<string>()
  private keyRules: Rule[] | null = null

  /** Nombre de valeurs connues. */
  get size(): number {
    return this.map.size
  }

  /** Nombre de noms de clés supplémentaires. */
  get keyCount(): number {
    return this.keys.size
  }

  /** Noms déclarés que les règles par défaut couvrent déjà (ignorés, signalés). */
  get coveredKeys(): string[] {
    return [...this.covered]
  }

  /**
   * Déclare un nom de clé à masquer partout où il apparaît avec une valeur
   * (sans connaître la valeur). Un nom déjà couvert par les règles par défaut
   * n'est pas ajouté, pour ne pas le compter deux fois.
   */
  learnKey(name: string): boolean {
    const k = name.trim().toUpperCase()
    if (!/^[A-Z_][A-Z0-9_]*$/.test(k) || this.keys.has(k)) return false
    if (BUILTIN_KEY.test(k) && !isParameterKey(k)) {
      this.covered.add(k)
      return false
    }
    this.keys.add(k)
    this.keyRules = null
    return true
  }

  /** Les règles « clé nommée » pour les noms déclarés ; vide si aucun. */
  rules(): Rule[] {
    if (this.keys.size === 0) return []
    if (this.keyRules) return this.keyRules
    this.keyRules = namedRules([...this.keys].join('|'), false)
    return this.keyRules
  }

  /**
   * Apprend une valeur, masquée ensuite partout où elle apparaît. Sans
   * `force`, seule une valeur qui ressemble à un secret est retenue
   * (`looksSecret`) ; `force` sert aux valeurs données explicitement dans
   * une liste, retenues dès 6 caractères.
   */
  learn(value: string, label: string, force = false): boolean {
    const v = unquote(value)
    if (v.includes('[REDACTED:') || isPlaceholder(v)) return false
    if (force ? v.length < MIN_VALUE_LENGTH : !looksSecret(v)) return false
    if (this.map.has(v)) return false
    this.map.set(v, label.toUpperCase())
    this.alternation = null
    return true
  }

  /** Apprend plusieurs valeurs d'un coup ; retourne le nombre ajouté. */
  learnAll(found: Found[]): number {
    let n = 0
    for (const f of found) if (this.learn(f.value, f.label)) n++
    return n
  }

  /**
   * Lit une liste utilisateur, une entrée par ligne :
   *   `LABEL=valeur`  valeur à masquer partout, sous ce label
   *   `NOM=`          nom de clé à masquer partout où il porte une valeur
   *   `valeur`        valeur à masquer partout, label LISTED
   * Lignes vides et `#` ignorées. Retourne le nombre d'entrées ajoutées.
   */
  learnList(text: string): number {
    let n = 0
    for (const raw of text.split(/\r?\n/)) {
      const line = raw.trim()
      if (line === '' || line.startsWith('#')) continue
      const m = /^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/.exec(line)
      let ok: boolean
      if (m && m[2]!.trim() === '') ok = this.learnKey(m[1]!)
      else if (m) ok = this.learn(m[2]!, m[1]!, true)
      else ok = this.learn(line, 'LISTED', true)
      if (ok) n++
    }
    return n
  }

  private regex(): RegExp | null {
    if (this.map.size === 0) return null
    if (this.alternation) return this.alternation
    // Les plus longues d'abord : une valeur contenue dans une autre ne doit pas gagner.
    const values = [...this.map.keys()].sort((a, b) => b.length - a.length)
    const escaped = values.map((v) => v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
    this.alternation = new RegExp(escaped.join('|'), 'g')
    return this.alternation
  }

  /** Masque toute occurrence littérale d'une valeur connue, hors marqueurs déjà posés. */
  apply(text: string): { text: string; count: number; labels: string[] } {
    const re = this.regex()
    if (!re) return { text, count: 0, labels: [] }
    let count = 0
    const labels = new Set<string>()
    // On ne touche pas l'intérieur des `[REDACTED:…]` : segmentation sur les marqueurs.
    const parts = text.split(MASK_RE)
    const masks = text.match(MASK_RE) ?? []
    const out = parts.map((seg) =>
      seg.replace(re, (v) => {
        count++
        const label = this.map.get(v) ?? 'KNOWN'
        labels.add(label)
        return MASK(label)
      }),
    )
    let rebuilt = ''
    for (let i = 0; i < out.length; i++) rebuilt += out[i] + (masks[i] ?? '')
    return { text: rebuilt, count, labels: [...labels] }
  }
}

/**
 * Masque les secrets d'un texte : règles, puis valeurs connues. Idempotent :
 * un texte déjà masqué ressort inchangé.
 */
export function redact(input: string, known?: KnownSecrets): Redaction {
  let text = input
  let count = 0
  const labels = new Set<string>()
  const found: Found[] = []
  for (const rule of [...RULES, ...(known?.rules() ?? [])]) {
    text = text.replace(rule.pattern, (m: string, ...rest: unknown[]) => {
      // Déjà masqué (idempotence) : on ne touche pas.
      if (m.includes('[REDACTED:')) return m
      const groups = rest.slice(0, -2) as string[]
      const out = rule.replace(m, ...groups)
      if (out === null) return m
      count++
      const label = rule.label ? rule.label(m, ...groups) : rule.name
      labels.add(label)
      found.push({ label, value: rule.value ? rule.value(m, ...groups) : m })
      return out
    })
  }
  if (known) {
    const k = known.apply(text)
    text = k.text
    count += k.count
    k.labels.forEach((l) => labels.add(l))
  }
  return { text, count, labels: [...labels], found }
}

/** Extrait les secrets d'un fichier sans produire de texte masqué. */
export function extract(input: string): Found[] {
  return redact(input).found
}

/** Ligne de synthèse pour le transcript et le contexte modèle. */
export function summary(r: Pick<Redaction, 'count' | 'labels'>, where: string): string {
  const what = r.labels.slice(0, 6).join(', ') + (r.labels.length > 6 ? ', …' : '')
  return `secret-redact : ${r.count} valeur${r.count > 1 ? 's' : ''} masquée${r.count > 1 ? 's' : ''} dans ${where} (${what})`
}
